package com.yeyamo_mobile.api.commerce_service.persistence;
import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;import static com.yeyamo_mobile.api.commerce_service.domain.CommerceTypes.*;
@Entity@Table(name="commerce_promotions")public class Promotion{
 @Id public UUID id;@Column(name="idempotency_key",unique=true)public String idempotencyKey;@Column(name="partner_id")public String partnerId;public String code;public String name;public String description;@Enumerated(EnumType.STRING)@Column(name="discount_type")public DiscountType discountType;@Column(name="discount_value")public BigDecimal discountValue;public String currency;@Column(name="maximum_discount")public BigDecimal maximumDiscount;@Column(name="minimum_order_amount")public BigDecimal minimumOrderAmount;@Column(name="usage_limit")public Long usageLimit;@Column(name="usage_limit_per_user")public Long usageLimitPerUser;@Column(name="usage_count")public long usageCount;@Column(name="starts_at")public Instant startsAt;@Column(name="ends_at")public Instant endsAt;@Column(name="applicable_product_types")public String applicableProductTypes;@Column(name="applicable_entity_ids")public String applicableEntityIds;@Enumerated(EnumType.STRING)public PromotionStatus status;@Version public long version;@Column(name="created_at")public Instant createdAt;@Column(name="updated_at")public Instant updatedAt;@PrePersist void create(){id=id==null?UUID.randomUUID():id;createdAt=updatedAt=Instant.now();}@PreUpdate void update(){updatedAt=Instant.now();}
}
